def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out"""
    # Simple approach: find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    # If no difference found in common length, check if one is longer
    if pos == -1:
        if len(s_in) != len(s_out):
            pos = min_len
        else:
            return None  # No difference

    # For insertion/deletion, we need to determine what changed
    # Let's look at the difference more carefully
    if len(s_in) < len(s_out):
        # Insertion
        old_sub = ""
        new_sub = s_out[pos]
        return (old_sub, new_sub, pos)
    elif len(s_in) > len(s_out):
        # Deletion  
        old_sub = s_in[pos]
        new_sub = ""
        return (old_sub, new_sub, pos)
    else:
        # Substitution
        old_sub = s_in[pos]
        new_sub = s_out[pos]
        return (old_sub, new_sub, pos)

